def choose_move(observation):
    def as_pos(v, default=None):
        if isinstance(v, dict):
            for k in ("position", "pos", "loc", "location", "xy"):
                if k in v:
                    v = v.get(k)
                    break
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return default
        return default

    def get_first(*keys, default=None):
        for k in keys:
            if isinstance(observation, dict) and k in observation:
                return observation.get(k)
        return default

    w = int(get_first("grid_width", "width", "cols", default=0) or 0)
    h = int(get_first("grid_height", "height", "rows", default=0) or 0)

    self_pos = as_pos(get_first("self_position", "agent_position", "player_position", "position", default=(0, 0)), (0, 0))
    opp_pos = as_pos(get_first("opponent_position", "enemy_position", "target_position", default=None), None)

    obstacles = set()
    for key in ("obstacles", "walls", "blocked", "blocks"):
        for p in get_first(key, default=[]) or []:
            q = as_pos(p, None)
            if q is not None:
                obstacles.add(q)

    resources = []
    for key in ("resources", "food", "items", "targets", "coins", "gems"):
        for p in get_first(key, default=[]) or []:
            q = as_pos(p, None)
            if q is not None:
                resources.append(q)

    enemies = []
    for key in ("enemies", "opponents", "enemy_positions", "opponent_positions", "players"):
        for p in get_first(key, default=[]) or []:
            q = as_pos(p, None)
            if q is not None and q != self_pos:
                enemies.append(q)

    if opp_pos is None and enemies:
        opp_pos = enemies[0]

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = [0, 0]
    best_score = None

    for dx, dy in moves:
        nx, ny = self_pos[0] + dx, self_pos[1] + dy
        if nx < 0 or ny < 0 or (w and nx >= w) or (h and ny >= h) or (nx, ny) in obstacles:
            continue

        score = 0

        if resources:
            dmin = min(dist((nx, ny), r) for r in resources)
            score += 50 - 8 * dmin

        if opp_pos is not None:
            do = dist((nx, ny), opp_pos)
            score += 2 * do
            if do == 0:
                score += 20
            elif do == 1:
                score += 6

        for e in enemies:
            de = dist((nx, ny), e)
            score += 1 * de

        if not resources and opp_pos is not None:
            score += 10 - dist((nx, ny), opp_pos)

        # Mild center bias when nothing else is known
        if w and h:
            cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
            score -= int(abs(nx - cx) + abs(ny - cy))

        if dx == 0 and dy == 0:
            score -= 1

        if best_score is None or score > best_score or (score == best_score and (dx, dy) < (best[0], best[1])):
            best_score = score
            best = [dx, dy]

    return best

